import { API_URL } from '../../config.js';
import { DbService } from '../../db/db.service.js';
import { refreshIfStale } from './snapshot-refresh.service.js';
import { ROW_ID_DEPENDENT_TABLES } from '@motivation/shared';
import type {
    DbDriver,
    PendingSyncChange,
    SyncPushChange,
    SyncPushFailureResponse,
    SyncPushSuccessResponse,
} from '@motivation/shared';

export type PendingChange = PendingSyncChange;

/**
 * Why a change left the queue without being applied. `server-rejection` is story
 * 267's case — the server gave a permanent verdict on that row.
 * `orphaned-dependent` is story 300's remainder: this client dropped the row
 * because the parent it hangs off never landed, so there was no request and no
 * status to report.
 */
export type QuarantineReason = 'server-rejection' | 'orphaned-dependent';

/** A pending change dropped from the queue, recorded before it goes (story 267). */
export interface QuarantinedChange {
    change: PendingChange;
    /**
     * The HTTP status that made the verdict permanent, or `null` when this
     * client decided on its own — there was no request, so there is no status
     * to report, and inventing one would read as the server's opinion.
     */
    status: number | null;
    /** The server's own reason verbatim, or ours when we made the call. */
    error: string;
    reason: QuarantineReason;
}

export type SyncResult =
    | { status: 'idle'; applied: 0; quarantined?: QuarantinedChange[] }
    | { status: 'synced'; applied: number; quarantined?: QuarantinedChange[] }
    | {
        status: 'failed';
        error: string;
        failedAt?: number;
        failedChange?: PendingChange;
        quarantined?: QuarantinedChange[];
    };

type SyncOptions = {
    driver?: DbDriver;
    dbService?: DbService;
    fetchImpl?: typeof fetch;
    /**
     * Story 133 — the tail-pull is now `refreshIfStale`, gated by the cheap
     * `/snapshot/info` check rather than the unconditional binary download.
     * Tests inject a stub to assert the call without going through the
     * full snapshot machinery.
     */
    refreshSnapshot?: typeof refreshIfStale;
};

function resolveDriver(driver?: DbDriver): DbDriver {
    return driver ?? DbService.getInstance().driver;
}

/**
 * Recovery hooks for the missing-`_pending_changes` path (story 190).
 * Injectable for tests; the default singleton also carries the one-shot
 * `attempted` state so a recovery that fails to reload can never loop
 * wipe→warn forever (the failure mode in the wf-2 instance forensics).
 */
export interface SyncRecoveryHooks {
    isBootstrapComplete: () => boolean;
    reload: () => void;
    attempted?: boolean;
}

const defaultRecoveryHooks: SyncRecoveryHooks = {
    isBootstrapComplete: () => DbService.getInstance().isBootstrapComplete,
    reload: () => window.location.reload(),
};

const isMissingPendingTableError = (error: unknown): error is Error =>
    error instanceof Error && error.message.includes('no such table: _pending_changes');

/**
 * Missing `_pending_changes` means one of two very different things:
 * - During bootstrap: the snapshot/schema init simply hasn't finished —
 *   transient, answer "no pending changes" and let the next poll succeed.
 *   Wiping here destroys the snapshot the bootstrap is importing (the wipe
 *   gets queued BEHIND the import on the worker's operation queue).
 * - After bootstrap: the local DB genuinely lacks its artifacts — recover
 *   once (wipe so the next boot re-downloads the snapshot, then reload).
 *   A second occurrence in the same session rethrows: fail loud, no loop.
 */
async function recoverFromMissingPendingTable(error: Error, hooks: SyncRecoveryHooks, caller: string): Promise<void> {
    if (!hooks.isBootstrapComplete()) {
        console.debug(`[SYNC-DEBUG][sync] ${caller} — _pending_changes missing during bootstrap; transient, no recovery`);
        return;
    }
    if (hooks.attempted) {
        console.error(`[SYNC-DEBUG][sync] ${caller} — _pending_changes still missing after a recovery attempt; failing loud`);
        throw error;
    }
    hooks.attempted = true;
    console.warn(`Local DB missing _pending_changes after bootstrap. Wiping OPFS and reloading once... [${caller}]`);
    try {
        await DbService.getInstance().wipe();
    } catch {
        // Ignore wipe errors — the reload + schema-validating exists() will re-bootstrap.
    }
    hooks.reload();
}

/**
 * Statuses that mean "this change will never apply, no matter how often it is
 * retried" — the server parsed the request and rejected *this row* (story 267).
 * 400 is what `POST /api/sync/push` returns for an apply/validation rejection
 * (`SyncApplyError` → `failed_at`); 409 is the conflict contract (story 265's
 * duplicate `external_id`); 422 covers semantic validation.
 *
 * Deliberately NOT permanent: every 5xx and network error (the server never
 * gave a verdict), 408/425/429 (explicit retry semantics) and 401/403 (a
 * configuration fault, not a bad change). Getting this backwards would throw
 * away real user data, so the verdict is the server's answer — never a retry
 * count.
 */
const PERMANENT_REJECTION_STATUSES = [400, 409, 422] as const;

function isPermanentRejection(status: number): boolean {
    return (PERMANENT_REJECTION_STATUSES as readonly number[]).includes(status);
}

/**
 * Drop a change from the queue — but never silently. Same contract as
 * `preservePendingChangesBeforeImport` in snapshot-refresh.service.ts: record
 * the row verbatim at error level first (the client log ships, so it stays
 * recoverable), then delete. The returned record is also carried out on the
 * `SyncResult` so the caller surfaces it.
 */
async function quarantinePendingChange(
    db: DbDriver,
    change: PendingChange,
    status: number | null,
    error: string,
    reason: QuarantineReason,
): Promise<QuarantinedChange> {
    const verdict = status === null
        ? `this client rejected it before pushing (${reason})`
        : `the server permanently rejected it with ${status}`;
    console.error(
        `[SYNC-DEBUG][sync] Quarantining pending change ${change.id} (${change.table_name} ${change.row_id}): ${verdict}, ` +
        `so retrying can only wedge the queue. It will NOT be pushed again — recording it verbatim first:`,
        { status, error, reason, change },
    );
    await SyncService.deletePendingChange(change.id, db);
    return { change, status, error, reason };
}

/*
 * Story 300's remainder, half one — "two local rows with the same `external_id`
 * must never reach the server's unique index" — needs NO code here, and a guard
 * for it was written, tested and then deleted rather than shipped. Three facts,
 * each checked rather than assumed:
 *
 *   1. The local database enforces the same rule. `idx_activities_external_id`
 *      is declared inside `HEALTH_TABLES_SQL`, so it reaches the client through
 *      both routes the local DB is ever built by — the offline fallback schema
 *      and the binary snapshot, which is a copy of the server's file. Two local
 *      rows holding one `external_id` cannot exist to be pushed.
 *   2. So the only real shape is a queued INSERT whose `external_id` the SERVER
 *      holds under a different row id — which is what the 2026-07-29 incident
 *      was. That is not knowable from the local mirror, because an import can
 *      never land on top of a queued change: `refreshIfStale`'s `preLoadCheck`
 *      vetoes the import while `pending > 0` on a baselined DB, and a
 *      no-baseline DB pushes the queue *first*
 *      (`preservePendingChangesBeforeImport`).
 *   3. A batch-local check is worse than nothing. `INSERT a` → `DELETE a` →
 *      `INSERT b` legitimately reuses one `external_id`, and the server applies
 *      that sequence in order without complaint; quarantining the second INSERT
 *      would discard a change the server would have accepted. Data loss, to
 *      prevent an error that cannot occur.
 *
 * What remains is the server's 409/400, which story 267 already quarantines, and
 * half two below — the dependents that used to be left behind when it did.
 */

/**
 * Story 300's remainder, half two: a dropped parent INSERT must take its
 * dependent rows with it. `cardio_details.activity_id` IS the activity id
 * (`ROW_ID_DEPENDENT_TABLES`), so once the activity never reaches the server the
 * queued distance row can only fail its foreign key — and a second quarantine on
 * the next push would report it as its own unrelated fault.
 *
 * Only an INSERT cascades. A rejected UPDATE or DELETE leaves the parent row on
 * the server exactly as it was, so its children still apply.
 */
function dependentsOf(parent: PendingChange, pending: PendingChange[]): PendingChange[] {
    if (parent.operation !== 'INSERT') return [];
    const children = ROW_ID_DEPENDENT_TABLES[parent.table_name] ?? [];
    if (children.length === 0) return [];
    return pending.filter((candidate) =>
        candidate.id !== parent.id
        && children.includes(candidate.table_name)
        && candidate.row_id === parent.row_id);
}

export class SyncService {
    static async listPendingChanges(driver?: DbDriver, recovery: SyncRecoveryHooks = defaultRecoveryHooks): Promise<PendingChange[]> {
        console.debug('[SYNC-DEBUG][sync] listPendingChanges() called');
        const db = resolveDriver(driver);
        try {
            const changes = await db.query<PendingChange>(
                `
                    SELECT id, table_name, row_id, operation, row_data, created_at
                    FROM _pending_changes
                    ORDER BY id ASC
                `,
            );
            console.debug('[SYNC-DEBUG][sync] listPendingChanges() returned', changes.length, 'changes');
            return changes;
        } catch (error) {
            if (isMissingPendingTableError(error)) {
                await recoverFromMissingPendingTable(error, recovery, 'listPendingChanges()');
                return [];
            }
            console.error('[SYNC-DEBUG][sync] listPendingChanges() — unexpected error:', error);
            throw error;
        }
    }

    static async getPendingCount(driver?: DbDriver, recovery: SyncRecoveryHooks = defaultRecoveryHooks): Promise<number> {
        console.debug('[SYNC-DEBUG][sync] getPendingCount() called');
        const db = resolveDriver(driver);
        try {
            const rows = await db.query<{ count: number }>('SELECT COUNT(*) AS count FROM _pending_changes');
            const count = Number(rows[0]?.count ?? 0);
            console.debug('[SYNC-DEBUG][sync] getPendingCount() =', count);
            return count;
        } catch (error) {
            if (isMissingPendingTableError(error)) {
                await recoverFromMissingPendingTable(error, recovery, 'getPendingCount()');
                return 0;
            }
            console.error('[SYNC-DEBUG][sync] getPendingCount() — unexpected error:', error);
            throw error;
        }
    }

    static async deletePendingChange(id: number, driver?: DbDriver): Promise<void> {
        const db = resolveDriver(driver);
        await db.execute('DELETE FROM _pending_changes WHERE id = ?', id);
    }

    static async deletePendingChangesFrom(startId: number, driver?: DbDriver): Promise<void> {
        const db = resolveDriver(driver);
        await db.execute('DELETE FROM _pending_changes WHERE id >= ?', startId);
    }

    static async deletePendingChangesUpTo(id: number, driver?: DbDriver): Promise<void> {
        const db = resolveDriver(driver);
        await db.execute('DELETE FROM _pending_changes WHERE id <= ?', id);
    }

    static async syncPendingChanges(options: SyncOptions = {}): Promise<SyncResult> {
        const {
            driver,
            dbService = DbService.getInstance(),
            fetchImpl = fetch,
            refreshSnapshot = refreshIfStale,
        } = options;

        const db = resolveDriver(driver);
        let totalApplied = 0;
        const quarantined: QuarantinedChange[] = [];
        // Only ever present when something was actually quarantined, so a clean
        // run's result shape is unchanged.
        const withQuarantined = (result: SyncResult): SyncResult => (
            quarantined.length > 0 ? { ...result, quarantined } : result
        );

        while (true) {
            const pending = await SyncService.listPendingChanges(db);
            if (pending.length === 0) {
                // Story 133 — gate the binary snapshot download behind the
                // cheap /snapshot/info check. The SW also fires `mark-dirty`
                // automatically after the push response, so this call is
                // typically redundant with the trigger-1 path; it exists for
                // the explicit user-driven Sync button (status screen) when
                // pending is already zero, which would otherwise return
                // without ever consulting the server.
                const refreshResult = await refreshSnapshot({ dbService, fetchImpl });

                if (refreshResult.status === 'failed') {
                    if (!navigator.onLine) {
                        console.debug('[SYNC-DEBUG][sync] Snapshot refresh failed offline; treating as success for applied changes.');
                        return withQuarantined(totalApplied === 0
                            ? { status: 'idle', applied: 0 }
                            : { status: 'synced', applied: totalApplied });
                    }
                    console.error('[SYNC-DEBUG][sync] Snapshot refresh failed:', refreshResult.error);
                    return withQuarantined({
                        status: 'failed',
                        error: refreshResult.error,
                    });
                }

                // 'fresh' | 'updated' | 'offline' | 'pending' — all acceptable terminal states.
                if (refreshResult.status === 'pending' && refreshResult.pendingCount > 0) {
                    console.debug('[SYNC-DEBUG][sync] Pending changes appeared during refresh; looping to push them.');
                    continue;
                }

                return withQuarantined(totalApplied === 0
                     ? { status: 'idle', applied: 0 }
                     : { status: 'synced', applied: totalApplied });
            }

            const changes: SyncPushChange[] = pending.map(({ id: _id, ...change }) => change);

            let response: Response;
            try {
                response = await fetchImpl(`${API_URL}/api/sync/push`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ changes }),
                });
            } catch (error) {
                // No verdict from the server — transient by definition. Keep the
                // queue intact and try again later.
                console.error('[SYNC-DEBUG][sync] Push request FAILED:', error);
                return withQuarantined({
                    status: 'failed',
                    error: error instanceof Error ? error.message : 'Sync request failed',
                });
            }

            console.debug('[SYNC-DEBUG][sync] Push response status:', response.status);

            if (!response.ok) {
                let failure: Partial<SyncPushFailureResponse> = {};
                try {
                    failure = await response.json() as SyncPushFailureResponse;
                } catch {
                    // fall through with default error text below
                }

                const failedAt = typeof failure.failed_at === 'number' ? failure.failed_at : undefined;
                const failedChange = typeof failedAt === 'number' ? pending[failedAt] : undefined;
                const error = failure.error ?? `Sync failed: ${response.status}`;

                // Story 267 — a permanent rejection the server pinned on ONE row
                // can never succeed. Retrying it forever wedges the queue, and
                // through `refreshIfStale`'s `pending > 0 && hasBaseline` guard it
                // wedges snapshot refresh with it (the 2026-07-29 incident, where
                // it only cleared because changes were dropped by hand). Quarantine
                // that row — recorded verbatim, never silently — and push the rest.
                // A rejection the server did NOT pin on a row (no `failed_at`)
                // blames the request, not a change: leave the queue alone.
                if (isPermanentRejection(response.status) && failedChange) {
                    if (quarantined.some((entry) => entry.change.id === failedChange.id)) {
                        // The delete did not take: looping would spin forever.
                        console.error(`[SYNC-DEBUG][sync] Pending change ${failedChange.id} was rejected again after being quarantined — the row did not leave _pending_changes.`);
                        return withQuarantined({ status: 'failed', error, failedAt, failedChange });
                    }
                    quarantined.push(await quarantinePendingChange(db, failedChange, response.status, error, 'server-rejection'));
                    // Story 300's remainder — the parent never landed, so its
                    // 1:1 children cannot. Carrying them out here is what stops
                    // the next push reporting a foreign-key failure as if it were
                    // an unrelated bad row.
                    for (const dependent of dependentsOf(failedChange, pending)) {
                        quarantined.push(await quarantinePendingChange(
                            db,
                            dependent,
                            null,
                            `Its parent ${failedChange.table_name} ${failedChange.row_id} was quarantined after the server rejected it `
                            + `with ${response.status}, so this row has no parent to attach to on the server.`,
                            'orphaned-dependent',
                        ));
                    }
                    continue;
                }

                return withQuarantined({
                    status: 'failed',
                    error,
                    failedAt,
                    failedChange,
                });
            }

            const success = await response.json() as SyncPushSuccessResponse;
            const appliedCount = Number(success.applied ?? pending.length);
            totalApplied += appliedCount;

            const lastId = pending[pending.length - 1].id;
            await SyncService.deletePendingChangesUpTo(lastId, db);
        }
    }
}
